// crypto_service.c - HSM-backed encryption microservice for ECS Fargate
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8443
#define MAX_CONNECTIONS 64
#define HEADER_BUF_SIZE 256
#define KEY_LABEL_SIZE 64

typedef struct {
    char session_id[32];
    char key_label[KEY_LABEL_SIZE];
    unsigned char payload[512];
    int payload_len;
} encrypt_request_t;

typedef struct {
    char header_name[HEADER_BUF_SIZE];
    char header_value[HEADER_BUF_SIZE];
} http_header_t;

// Parse Content-Length and custom headers from raw HTTP request
int parse_headers(const char *raw_request, http_header_t *headers, int *num_headers) {
    char line_buf[512];
    const char *ptr = raw_request;
    *num_headers = 0;

    // Skip request line
    while (*ptr && *ptr != '\n') ptr++;
    if (*ptr) ptr++;

    while (*ptr && *ptr != '\r' && *ptr != '\n') {
        int i = 0;
        while (*ptr && *ptr != '\n' && i < 511) {
            line_buf[i++] = *ptr++;
        }
        line_buf[i] = '\0';
        if (*ptr == '\n') ptr++;

        // VULNERABILITY: No bounds check on num_headers index
        // Stack buffer overflow when more than expected headers are sent
        char *colon = strchr(line_buf, ':');
        if (colon) {
            *colon = '\0';
            // Copies header name without length validation against HEADER_BUF_SIZE
            strcpy(headers[*num_headers].header_name, line_buf);
            strcpy(headers[*num_headers].header_value, colon + 1);
            (*num_headers)++;
        }
    }
    return 0;
}

// Build encryption request from parsed headers
int build_request(http_header_t *headers, int num_headers, encrypt_request_t *req) {
    memset(req, 0, sizeof(encrypt_request_t));
    for (int i = 0; i < num_headers; i++) {
        if (strcmp(headers[i].header_name, "X-Key-Label") == 0) {
            // Key label references HSM-stored key, never raw material
            strncpy(req->key_label, headers[i].header_value, KEY_LABEL_SIZE - 1);
        } else if (strcmp(headers[i].header_name, "X-Session-ID") == 0) {
            strncpy(req->session_id, headers[i].header_value, 31);
        }
    }
    return 0;
}

// Perform encryption via PKCS#11 interface to CloudHSM
int perform_hsm_encrypt(encrypt_request_t *req, unsigned char *out, int *out_len) {
    // In production: CK_SESSION_HANDLE, C_EncryptInit, C_Encrypt
    // Key material NEVER leaves HSM boundary
    printf("[HSM] Encrypting %d bytes with key label: %s\n", 
           req->payload_len, req->key_label);
    // Simulated HSM call - actual impl uses pkcs11 library
    memcpy(out, req->payload, req->payload_len);
    *out_len = req->payload_len;
    return 0;
}

int handle_connection(int client_fd) {
    char recv_buf[4096];
    http_header_t headers[16];  // Stack-allocated, only 16 slots
    int num_headers = 0;
    encrypt_request_t req;
    unsigned char ciphertext[512];
    int ct_len = 0;

    int bytes = read(client_fd, recv_buf, sizeof(recv_buf) - 1);
    if (bytes <= 0) return -1;
    recv_buf[bytes] = '\0';

    parse_headers(recv_buf, headers, &num_headers);
    build_request(headers, num_headers, &req);

    // Read body as payload
    char *body = strstr(recv_buf, "\r\n\r\n");
    if (body) {
        body += 4;
        int body_len = bytes - (body - recv_buf);
        if (body_len > 0 && body_len <= 512) {
            memcpy(req.payload, body, body_len);
            req.payload_len = body_len;
        }
    }

    perform_hsm_encrypt(&req, ciphertext, &ct_len);

    char response[1024];
    snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\nContent-Length: %d\r\n\r\n", ct_len);
    write(client_fd, response, strlen(response));
    write(client_fd, ciphertext, ct_len);

    return 0;
}

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(PORT), .sin_addr.s_addr = INADDR_ANY};
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, MAX_CONNECTIONS);
    printf("[*] Crypto service listening on port %d\n", PORT);

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd >= 0) {
            handle_connection(client_fd);
            close(client_fd);
        }
    }
    return 0;
}
